import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CdvW4CUT.js";const k=JSON.parse('{"title":"架构与目录","description":"CertHub 的技术栈、代码结构、关键模块、主要接口与冒烟测试。","frontmatter":{"title":"架构与目录","description":"CertHub 的技术栈、代码结构、关键模块、主要接口与冒烟测试。"},"headers":[],"relativePath":"docs/dev.md","filePath":"docs/dev.md","lastUpdated":null}'),e={name:"docs/dev.md"};function p(d,s,l,r,h,o){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="架构与目录" tabindex="-1">架构与目录 <a class="header-anchor" href="#架构与目录" aria-label="Permalink to &quot;架构与目录&quot;">​</a></h1><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>选择</th></tr></thead><tbody><tr><td>后端</td><td>Python 3.11+ / FastAPI / SQLAlchemy 2 / SQLite（可切 PostgreSQL、MySQL）</td></tr><tr><td>调度</td><td>APScheduler（定时流水线、站点巡检、到期提醒）</td></tr><tr><td>密码学</td><td>cryptography（密钥、CSR、证书解析、PFX / P7B 导出）</td></tr><tr><td>ACME</td><td>自研 ACME v2 客户端（JWS 签名、订单、挑战、EAB）</td></tr><tr><td>远程执行</td><td>paramiko（SSH / SFTP）</td></tr><tr><td>前端</td><td>React 19 + Vite 6 + TypeScript + Tailwind CSS v4 + shadcn/ui 风格组件</td></tr><tr><td>状态与路由</td><td>TanStack Query + react-router-dom 7（HashRouter，兼容后端静态托管）</td></tr></tbody></table><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>certd-lite/</span></span>
<span class="line"><span>├── backend/</span></span>
<span class="line"><span>│   ├── app/</span></span>
<span class="line"><span>│   │   ├── main.py            # 入口、路由注册、静态托管、安全响应头</span></span>
<span class="line"><span>│   │   ├── config.py          # 配置（环境变量覆盖）</span></span>
<span class="line"><span>│   │   ├── db.py / models.py  # 数据库与模型</span></span>
<span class="line"><span>│   │   ├── security.py        # 密码哈希、JWT、AES-GCM 加密</span></span>
<span class="line"><span>│   │   ├── plugins.py         # ★ 插件元数据注册表（驱动前端表单）</span></span>
<span class="line"><span>│   │   ├── templates.py       # 流水线模板</span></span>
<span class="line"><span>│   │   ├── defaults.py        # 系统设置默认值</span></span>
<span class="line"><span>│   │   ├── permissions.py     # 功能权限键</span></span>
<span class="line"><span>│   │   ├── deps.py            # 依赖注入、统一响应、审计</span></span>
<span class="line"><span>│   │   ├── routers/           # auth / pipeline / history / access / cert / monitor ...</span></span>
<span class="line"><span>│   │   └── services/</span></span>
<span class="line"><span>│   │       ├── engine.py      # 流水线执行引擎（阶段、任务、变量、失败跳转）</span></span>
<span class="line"><span>│   │       ├── acme.py        # ACME v2 客户端</span></span>
<span class="line"><span>│   │       ├── dns.py         # 6 家 DNS 服务商适配</span></span>
<span class="line"><span>│   │       ├── deploy*.py     # 75 个部署插件（按厂商拆文件）</span></span>
<span class="line"><span>│   │       ├── notify.py      # 10 种通知渠道</span></span>
<span class="line"><span>│   │       ├── logbus.py      # 进程内日志发布/订阅（SSE）</span></span>
<span class="line"><span>│   │       ├── scheduler.py   # 定时调度</span></span>
<span class="line"><span>│   │       └── net.py         # 代理与反向代理</span></span>
<span class="line"><span>│   ├── data/                  # SQLite、证书文件、secret.key（运行时生成）</span></span>
<span class="line"><span>│   ├── tools/                 # backup.py、fetch_access_logos.py</span></span>
<span class="line"><span>│   └── requirements.txt</span></span>
<span class="line"><span>├── webui/                     # 前端源码（React）</span></span>
<span class="line"><span>├── frontend/dist/             # 前端构建产物（后端托管这个目录）</span></span>
<span class="line"><span>├── website/                   # 本站（VitePress）</span></span>
<span class="line"><span>├── tests/smoke.py             # 接口冒烟</span></span>
<span class="line"><span>└── start.bat / start.sh</span></span></code></pre></div><h2 id="元数据驱动" tabindex="-1">元数据驱动 <a class="header-anchor" href="#元数据驱动" aria-label="Permalink to &quot;元数据驱动&quot;">​</a></h2><p>新增签发方式 / 部署目标 / DNS 服务商 / 通知渠道，<strong>只改后端</strong> <code>plugins.py</code> 的注册表：</p><table tabindex="0"><thead><tr><th>注册表</th><th>作用</th></tr></thead><tbody><tr><td><code>TASK_PLUGINS</code></td><td>任务插件（申请 / 部署 / 通知）及其表单字段</td></tr><tr><td><code>ACCESS_TYPES</code></td><td>授权类型及其表单字段</td></tr><tr><td><code>NOTIFY_TYPES</code></td><td>通知渠道及其字段</td></tr><tr><td><code>ACME_PROVIDERS</code></td><td>CA 名称、目录地址、是否要 EAB</td></tr></tbody></table><p>前端表单、授权下拉、任务选择器、概览页的「支持的证书」全部由这些元数据自动生成，<strong>不要在前端硬编码插件清单</strong>。</p><p>字段的敏感属性由 <code>component == &quot;password&quot;</code> 声明，不靠字段名猜。字段还可以声明动作按钮（<code>action</code>），例如群晖的「获取设备 ID」。</p><h2 id="主要接口" tabindex="-1">主要接口 <a class="header-anchor" href="#主要接口" aria-label="Permalink to &quot;主要接口&quot;">​</a></h2><p>所有业务接口返回统一信封：<code>{ code, msg, data }</code>，鉴权用请求头 <code>Authorization: &lt;token&gt;</code>。</p><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>POST /api/auth/login</code></td><td>登录，返回 <code>token</code> / <code>refreshToken</code></td></tr><tr><td><code>GET /api/auth/captcha</code></td><td>图形验证码（失败次数达到阈值后要求）</td></tr><tr><td><code>GET /api/pipeline/plugins</code></td><td>任务插件元数据</td></tr><tr><td><code>GET /api/pipeline/list</code></td><td>流水线列表（分页）</td></tr><tr><td><code>GET /api/pipeline/templates</code></td><td>模板列表</td></tr><tr><td><code>POST /api/pipeline/from-template</code></td><td>按模板创建</td></tr><tr><td><code>POST /api/pipeline/{id}/run</code></td><td>运行，立即返回 <code>historyId</code></td></tr><tr><td><code>POST /api/pipeline/{id}/stage/run</code></td><td>单独运行某个阶段</td></tr><tr><td><code>POST /api/pipeline/batch</code></td><td>批量运行 / 启停 / 改定时 / 删除</td></tr><tr><td><code>GET /api/history/{id}/stream</code></td><td><strong>SSE</strong> 实时日志（历史记录则回放）</td></tr><tr><td><code>POST /api/history/{id}/stop</code></td><td>协作式停止</td></tr><tr><td><code>GET /api/access/options?types=a,b</code></td><td>授权下拉（按精确类型过滤）</td></tr><tr><td><code>POST /api/access/{id}/test</code></td><td>测试授权连通性</td></tr><tr><td><code>POST /api/access/synology/device-id</code></td><td>换取群晖受信设备令牌</td></tr><tr><td><code>GET /api/cert/list</code></td><td>证书库</td></tr><tr><td><code>POST /api/cert/import</code></td><td>导入自有证书</td></tr><tr><td><code>GET /api/cert/{id}/download</code></td><td>导出 PEM / DER / PFX / P7B / JKS / Nginx</td></tr><tr><td><code>GET /api/monitor/site/list</code></td><td>站点监控列表</td></tr><tr><td><code>GET /api/settings</code></td><td>系统设置（site / security / notify / network）</td></tr><tr><td><code>GET /api/health</code></td><td>健康检查（异常返回 503）</td></tr></tbody></table><h2 id="开放接口" tabindex="-1">开放接口 <a class="header-anchor" href="#开放接口" aria-label="Permalink to &quot;开放接口&quot;">​</a></h2><p>给脚本 / CI 用的独立命名空间，用 API 密钥鉴权（<strong>不用</strong> JWT）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-api-key: ck_xxx&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-api-secret: yyy&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     http://127.0.0.1:8000/api/open/v1/pipelines</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-api-key: ck_xxx&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-api-secret: yyy&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     http://127.0.0.1:8000/api/open/v1/pipelines/7/run</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-api-key: ck_xxx&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-api-secret: yyy&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     http://127.0.0.1:8000/api/open/v1/certs</span></span></code></pre></div><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>GET /api/open/v1/pipelines</code></td><td>列出流水线</td></tr><tr><td><code>POST /api/open/v1/pipelines/{id}/run</code></td><td>触发运行</td></tr><tr><td><code>GET /api/open/v1/certs</code></td><td>最近 100 张证书</td></tr><tr><td><code>GET /api/open/v1/certs/{id}</code></td><td>单张证书详情</td></tr></tbody></table><p>密钥管理（创建 / 删除）走登录态接口 <code>/api/open/keys</code>，secret 只在创建时返回一次。</p><h2 id="前端开发" tabindex="-1">前端开发 <a class="header-anchor" href="#前端开发" aria-label="Permalink to &quot;前端开发&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webui</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # http://localhost:5174，/api 代理到 127.0.0.1:8000</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 产物 webui/dist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 构建并复制到 ../frontend/dist（后端托管的目录）</span></span></code></pre></div><p>目录约定：<code>src/components/ui</code> 是设计系统，<code>src/components/layout</code> 是外壳与导航，<code>src/features/&lt;域&gt;</code> 按页面拆分，<code>src/lib</code> 放 http、类型与 SSE 日志 hook。</p><h2 id="冒烟测试" tabindex="-1">冒烟测试 <a class="header-anchor" href="#冒烟测试" aria-label="Permalink to &quot;冒烟测试&quot;">​</a></h2><p>后端启动后跑接口冒烟（覆盖鉴权、分页、插件一致性、加密、限速等断言）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/smoke.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --password</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 123456</span></span></code></pre></div><p>新增插件、改了注册表、动了引擎之后都应该跑一遍再提交。</p>`,25)])])}const y=t(e,[["render",p]]);export{k as __pageData,y as default};
